css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .leyenda{display: flex; gap: 22px; align-items: flex-end; border: 1.5px dashed #000; border-radius: 8px; padding: 6px 12px; margin-bottom: 10px;}
.mz .ley-item{display: flex; align-items: flex-end; gap: 6px; font-size: 12.5px; font-weight: 600;}
.mz .ley-item .txt{padding-bottom: 2px;}
.mz .material-fila{display: flex; align-items: flex-end; gap: 16px; border: 1.2px solid var(--bosque); border-radius: 8px; padding: 7px 12px; margin-bottom: 7px;}
.mz .mat-grupo{display: flex; gap: 3px; align-items: flex-end;}
.mz .material-fila .caja-res{margin-left: auto; width: 92px; height: 38px; border: 1.5px solid var(--bosque); border-radius: 6px; align-self: center;}
.mz .cdu-fila{display: flex; align-items: center; gap: 12px; font-size: 18px; font-weight: 700; margin-bottom: 9px; flex-wrap: wrap;}
.mz .cdu-fila .num-grande{min-width: 56px;}
.mz .cdu-fila .casilla{display: flex; align-items: center; gap: 5px; font-size: 14px;}
.mz .cdu-fila .casilla .caja-mini{width: 44px; height: 34px; border: 1.5px solid var(--bosque); border-radius: 6px;}
.mz .rodear-fila{display: flex; gap: 14px; flex-wrap: wrap; font-size: 21px; font-weight: 700;}
.mz .rodear-fila .op{border: 1.5px solid var(--bosque); border-radius: 8px; padding: 6px 16px;}
.mz .dibujar-fila{display: flex; gap: 12px; align-items: stretch; margin-bottom: 8px;}
.mz .dibujar-fila .num-objetivo{display: flex; align-items: center; justify-content: center; font-size: 26px; font-weight: 700; border: 1.5px solid var(--bosque); border-radius: 8px; width: 90px; flex-shrink: 0;}
.mz .dibujar-fila .zona-libre{flex: 1; border: 1.5px solid var(--bosque); border-radius: 8px; height: 78px;}
